'use strict';
// Independent Pillow 12.3.0 JPEG encoder: 19x17 deterministic RGB gradient; no production encoder.
const encoded = {
  "rgb": "",
  "subsampled": "",
  "gray": "",
  "restart": "",
  "progressive": "",
  "cmyk": ""
};
module.exports = Object.fromEntries(Object.entries(encoded).map(([key, value]) => [key, Buffer.from(value, 'base64')]));
